/* =========================================================
   CHATPHETCH GROUP
   INDEX FOOTER
   USE ABOUT.HTML FOOTER DESIGN
   ========================================================= */

(function () {

    "use strict";


    function buildIndexFooter() {

        /*
         * Remove footer generated by customer-master-nav.js
         */
        document
            .querySelectorAll(".customer-footer")
            .forEach(function (footer) {
                footer.remove();
            });


        /*
         * Remove floating phone generated
         * by customer-master-nav.js
         */
        document
            .querySelectorAll(".customer-floating-phone")
            .forEach(function (button) {
                button.remove();
            });


        /*
         * Prevent duplicate footer
         */
        if (
            document.querySelector(
                ".cp-about-footer"
            )
        ) {
            return;
        }


        /* =====================================================
           FOOTER
           ===================================================== */

        const footer =
            document.createElement("footer");

        footer.className =
            "cp-about-footer";


        /* =====================================================
           CONTAINER
           ===================================================== */

        const container =
            document.createElement("div");

        container.className =
            "cp-footer-container";


        /* =====================================================
           MAIN
           ===================================================== */

        const main =
            document.createElement("div");

        main.className =
            "cp-footer-main";


        /* =====================================================
           BRAND
           ===================================================== */

        const brand =
            document.createElement("div");

        brand.className =
            "cp-footer-brand";


        const logoLink =
            document.createElement("a");

        logoLink.className =
            "cp-footer-logo";

        logoLink.href =
            "index.html";

        logoLink.setAttribute(
            "aria-label",
            "CHATPHETCH GROUP"
        );


        const logo =
            document.createElement("img");

        logo.src =
            "assets/logo.png";

        logo.alt =
            "CHATPHETCH GROUP";


        const logoText =
            document.createElement("div");

        logoText.className =
            "cp-footer-logo-text";


        const brandName =
            document.createElement("strong");

        brandName.textContent =
            "CHATPHETCH GROUP";


        const brandSub =
            document.createElement("small");

        brandSub.textContent =
            "FLOORING & CONSTRUCTION";


        logoText.appendChild(
            brandName
        );

        logoText.appendChild(
            brandSub
        );


        logoLink.appendChild(
            logo
        );

        logoLink.appendChild(
            logoText
        );


        /* =====================================================
           DESCRIPTION
           ===================================================== */

        const description =
            document.createElement("p");

        description.className =
            "cp-footer-description";

        description.textContent =
            "🌹 โรงงานผลิต-จำหน่าย วัสดุงานพื้นทุกประเภท 🌹";


        /* =====================================================
           TAGLINE
           ===================================================== */

        const tagline =
            document.createElement("p");

        tagline.className =
            "cp-footer-tagline";

        tagline.innerHTML =
            "♠️ สร้างสรรค์ผลงาน" +
            "&nbsp;&nbsp;" +
            "♠️ มาตรฐานเข้าถึง" +
            "&nbsp;&nbsp;" +
            "♠️ ยืน 1 คุณภาพ" +
            "<br>" +
            "บริการให้คำปรึกษาเกี่ยวกับพื้นทุกระบบแบบครบวงจร";


        brand.appendChild(
            logoLink
        );

        brand.appendChild(
            description
        );

        brand.appendChild(
            tagline
        );


        /* =====================================================
           MENU
           ===================================================== */

        const menu =
            document.createElement("div");

        menu.className =
            "cp-footer-menu";


        const menuTitle =
            document.createElement("div");

        menuTitle.className =
            "cp-footer-menu-title";

        menuTitle.textContent =
            "MENU";


        const links =
            document.createElement("div");

        links.className =
            "cp-footer-links";


        const menuItems = [

            {
                text: "หน้าแรก",
                href: "index.html"
            },

            {
                text: "เกี่ยวกับเรา",
                href: "about.html"
            },

            {
                text: "สินค้า",
                href: "products.html"
            },

            {
                text: "บริการ",
                href: "services.html"
            },

            {
                text: "ผลงาน",
                href: "projects.html"
            },

            {
                text: "ติดต่อเรา",
                href: "contact.html"
            }

        ];


        menuItems.forEach(
            function (item) {

                const link =
                    document.createElement("a");

                link.href =
                    item.href;

                link.textContent =
                    item.text;

                links.appendChild(
                    link
                );

            }
        );


        menu.appendChild(
            menuTitle
        );

        menu.appendChild(
            links
        );


        /* =====================================================
           MAIN APPEND
           ===================================================== */

        main.appendChild(
            brand
        );

        main.appendChild(
            menu
        );


        /* =====================================================
           BOTTOM
           ===================================================== */

        const bottom =
            document.createElement("div");

        bottom.className =
            "cp-footer-bottom";


        /* =====================================================
           COPYRIGHT
           ===================================================== */

        const copyright =
            document.createElement("div");

        copyright.className =
            "cp-footer-copy";

        copyright.innerHTML =
            "© 2026 " +
            "<strong>" +
            "CHATPHETCH GROUP CO., LTD." +
            "</strong>" +
            " All Rights Reserved.";


        /* =====================================================
           ADDRESS
           ===================================================== */

        const address =
            document.createElement("div");

        address.className =
            "cp-footer-address";


        const pin =
            document.createElement("span");

        pin.className =
            "cp-footer-pin";

        pin.textContent =
            "📍";


        const addressText =
            document.createElement("span");

        addressText.textContent =
            "10/1 ม.9 ต.นาหม่อม อ.นาหม่อม จ.สงขลา 90310";


        address.appendChild(
            pin
        );

        address.appendChild(
            addressText
        );


        /* =====================================================
           ACTIONS
           ===================================================== */

        const actions =
            document.createElement("div");

        actions.className =
            "cp-footer-actions";


        const contact =
            document.createElement("a");

        contact.className =
            "cp-footer-action";

        contact.href =
            "contact.html";

        contact.innerHTML =
            "☎" +
            "<span>ติดต่อเรา</span>";


        const order =
            document.createElement("a");

        order.className =
            "cp-footer-action";

        order.href =
            "order-status.html";

        order.innerHTML =
            "🔎" +
            "<span>ติดตามคำสั่งซื้อ</span>";


        actions.appendChild(
            contact
        );

        actions.appendChild(
            order
        );


        /* =====================================================
           SOCIAL
           ===================================================== */

        const social =
            document.createElement("div");

        social.className =
            "cp-footer-social";


        const facebook =
            document.createElement("a");

        facebook.href =
            "https://www.facebook.com/ChatphetchGroup";

        facebook.target =
            "_blank";

        facebook.rel =
            "noopener";

        facebook.setAttribute(
            "aria-label",
            "Facebook"
        );

        facebook.textContent =
            "f";


        const youtube =
            document.createElement("a");

        youtube.href =
            "#";

        youtube.setAttribute(
            "aria-label",
            "YouTube"
        );

        youtube.textContent =
            "▶";


        const line =
            document.createElement("a");

        line.className =
            "line";

        line.href =
            "#";

        line.setAttribute(
            "aria-label",
            "LINE"
        );

        line.textContent =
            "LINE";


        social.appendChild(
            facebook
        );

        social.appendChild(
            youtube
        );

        social.appendChild(
            line
        );


        /* =====================================================
           BOTTOM APPEND
           ===================================================== */

        bottom.appendChild(
            copyright
        );

        bottom.appendChild(
            address
        );

        bottom.appendChild(
            actions
        );

        bottom.appendChild(
            social
        );


        /* =====================================================
           CONTAINER APPEND
           ===================================================== */

        container.appendChild(
            main
        );

        container.appendChild(
            bottom
        );


        footer.appendChild(
            container
        );


        /*
         * Put footer at very bottom
         */
        document.body.appendChild(
            footer
        );


        /* =====================================================
           FLOATING CONTACT
           ===================================================== */

        const floating =
            document.createElement("div");

        floating.className =
            "cp-index-floating-contact";


        const phone =
            document.createElement("a");

        phone.href =
            "tel:0856299778";

        phone.title =
            "ฝ่ายเทคนิค";

        phone.setAttribute(
            "aria-label",
            "โทรหา CHATPHETCH GROUP"
        );

        phone.textContent =
            "☎";


        const facebookFloat =
            document.createElement("a");

        facebookFloat.href =
            "https://www.facebook.com/ChatphetchGroup";

        facebookFloat.target =
            "_blank";

        facebookFloat.rel =
            "noopener";

        facebookFloat.title =
            "Facebook";

        facebookFloat.textContent =
            "f";


        floating.appendChild(
            phone
        );

        floating.appendChild(
            facebookFloat
        );


        document.body.appendChild(
            floating
        );

    }


    /* =========================================================
       START
       ========================================================= */

    if (
        document.readyState ===
        "loading"
    ) {

        document.addEventListener(
            "DOMContentLoaded",
            buildIndexFooter
        );

    } else {

        buildIndexFooter();

    }

})();
